// What the mod keeps between one stop and the next. One object, made afresh each time the plugin loads: a reload (a changed setting, a
// hot reload) starts from nothing, and what must survive a reload does not belong here.

import type { CompactCheck } from './compact-check'
import type { Countdown } from './countdown'
import type { Asap, Attempt, Later } from './decide'
import type { Still } from './handoff'
import type { Lifetime } from './idle-handoff'
import type { LevelMemo } from './log'
import { freshPairing, type Pairing, type Stop } from './pairing'

// How the awaited turn of the handoff command ended: with its answer, or without one and why.
export type Ended = { answer: string; rejected?: true } | { failure: string; cancelled?: true }

// A pause of the session: when it began (`since`, which the line at the return counts from) and the size of the transcript then (`size`,
// none where it could not be told). The step reads a transcript too large to read whole from there, so that a compact marked in the pause is
// read however much it wrote after its mark.
export type Pause = { since: number; size: number | undefined }

// A handoff written in a pause and not yet handed over; in a dry run only the time it would have been written.
// `since` is the end of the answer the pause began after.
export type IdlePrepared = { kind: 'real'; text: string; file?: string; since: number } | { kind: 'simulated'; since: number }

// A handover runs, the handoff after a long pause is being written, or the message that came back after it is judged: either way the
// session is the mod's for the moment.
export const underWay = (state: { handingOver: boolean; preparing: boolean; returning: boolean }): boolean =>
  state.handingOver || state.preparing || state.returning

// The log level of the latest read (`LevelMemo`), which every handler that logs makes at its start; a line written outside a handler, as
// from a timer, goes by it.
export type State = LevelMemo & {
  // Not kept across a reload, on purpose: a reload is the person changing a setting or the developer reloading the mod, and an unattended
  // session cannot cause one, so the gap still limits every loop that can run without anyone there. A person who reloads after a failed
  // handoff wants the next try at once, which a kept record would hold back for minutes.
  // `turns` is the user's prompt count of the transcript, which a /clear starts over (docs/host-behaviour.md, `/clear` and the session).
  // `decide` ends the gap by minutes as well as by turns, so a count that fell cannot hold the lock for good.
  lastAttempt: Attempt | undefined
  // The stop of the main loop and the end of its turn, which are judged together.
  pairing: Pairing
  // What the stop last said, so that a long wait or a repeated failure is said once and not at every stop: the reason of a postponement, or
  // the line of a failure to check. Cleared by anything else the stop says (or by nothing to say), so that what returns is said again.
  said: string | undefined
  // The message about invalid settings and the command are introduced once per load, whether the load came with a session start or into a session that was
  // already running.
  introduced: boolean
  // True from the decision to hand over until the handoff has succeeded or failed. The command's own turn ends in a stop of its own, which
  // is no pause to act on (nor to report as postponed), whatever the gap says.
  handingOver: boolean
  // Set while the end of the command's turn is awaited; `own` is the first turn that starts after the wait began: the command's.
  // `rejected`: the user declined a permission in that turn (Esc or "No"), seen by the `tool.call` hook.
  turnWait: { own: string | undefined; rejected?: true; end: (result: Ended) => void } | undefined
  // What the person typed while the handoff ran, in order, and has not been put in yet: what went into the first message (or the pending
  // one) is taken out.
  held: string[]
  // The store key of the first message that has not reached the fresh session. Kept here as well as in the store so that a redelivery only ever
  // touches this session's own message and never one that another session left behind.
  pending: string | undefined
  // The session `/clear` made, where that pending message belongs: `redeliver` submits it nowhere else. Unset where it could not be read, and for
  // typing that was parked without a `/clear`.
  pendingIn: string | undefined
  // The next handover moved back by `/sweet-spot later`, until it is spent or the context shrinks below where it was asked. Kept here
  // only: a reload forgets it, like a change in /config.
  later: Later | undefined
  // A handover asked for with `/sweet-spot asap`, until a handover begins (spent, whether it goes through or not). Kept here only, like `later`.
  asap: Asap | undefined
  // What the last stop of the main loop said about background tasks and timers, which nothing else reads: `asap` at rest judges from it. It goes
  // at the start of a turn and at the end of the session, when it no longer holds, and then what runs is not known. Kept as the stop said it:
  // every count is derived where it is read, so none can disagree with the list.
  lastStop: Pick<Stop, 'background_tasks' | 'session_crons'> | undefined
  // The step that starts the handover of `asap` at rest is planned and has not begun; a second `asap` must not plan another.
  asapScheduled: boolean
  // A redelivery is under way: a second one would submit the message twice.
  redelivering: boolean
  // From the start of a turn of the main loop to its end, however it ended. The command runs at once while an answer runs (it is
  // `immediate`), and a redelivery, which submits a message, waits for it.
  answerRunning: boolean
  // Set once a handoff has succeeded: the context it left, and how many pauses of the fresh session were logged against it. Only a debug line reads it.
  afterHandoff: { before: number; pauses: number } | undefined
  // What still runs, fixed where the handover is decided and read where its first message is written: in between the list in `lastStop` can
  // go (a turn starts) or change (the command's own turn). Set only while that first message is written.
  still: Still | undefined
  // Whether the last compact was enough, found out at the first tool call or pause after it (`compact-check.ts`). Not kept across a reload, like the rest: at worst
  // one compact more follows.
  compactCheck: CompactCheck
  // The countdown before an automatic handover, while it runs. A reload drops it, and with it the handover it would have started.
  countdown: Countdown | undefined
  // The pauses past the threshold where no handover began, a draft waited or the countdown begun there ended without one, and the context
  // at the first of them. Two give a countdown that typing does not stop. Typing does not end it: only a handover that began, a later
  // handover asked for (the command or Not now) and a context that shrank below `from`.
  deferred: { pauses: number; from: number } | undefined
  // The session `/clear` made for a handoff of the mod. Unlike `pendingIn` it stays once the handoff is in: the first request of that session
  // is the handoff, which is not what the project starts with, and must not become its baseline.
  deliveredInto: string | undefined
  // True while the handoff after a long pause is written. It holds what `handingOver` holds (see `underWay`): the mod's own work is no pause
  // and no turn of the person's.
  preparing: boolean
  // True from the message that came back after the handoff was written, which takes it at once, until that message is judged: a second
  // message meanwhile is held and never sees the handoff. A switch to a fresh session hands on to `handingOver`.
  returning: boolean
  // What the handoff after a long pause knows of the session (idle-handoff.ts). `touch` is when the main loop last read or wrote the cache:
  // the start of its last request. `read` is due at the first turn of every session, since a /clear does not reload the mod but ends what was
  // known, and stays due while the transcript read holds no answer yet. `fresh`: the session began with no conversation (a start or a
  // /clear), so its first request is the project's baseline.
  idle: {
    // The step that writes the handoff, planned at the end of an answer, with its pause (kept for a compact that holds the step back and
    // plans it again); and the handoff written, until the person comes back or the pause ends.
    timer: ({ cancel: () => void } & Pause) | undefined
    prepared: IdlePrepared | undefined
    // The pause ended while the handoff was being written (a turn not the command's, a compact, a change of model): why, so that the handoff
    // that comes is dropped.
    endedWhilePreparing: string | undefined
    // The read once more a few seconds after a pause that found no answer in the transcript yet, which plans the pause if it can.
    reread: { cancel: () => void } | undefined
    // The step that shows the band once the handoff written has gone cold, and whether it shows.
    coldTimer: { cancel: () => void } | undefined
    coldShown: boolean
    // After a warm return the first request of the next turn shows whether the handoff written really kept the cache: it is checked
    // against the context at the return (`checkAgainst`), not against the request, which may carry a long message of its own. One
    // that missed it means it did not: from then on in the session (`doubted`) writing the handoff no longer moves the touch.
    checkAgainst: number | undefined
    doubted: boolean
    touch: number | undefined
    lifetime: Lifetime | undefined
    baseline: number | undefined
    read: boolean
    fresh: boolean
    baselineDue: boolean
    transcript: string | undefined
    unreadSaid: boolean
  }
}

export const freshIdle = (): State['idle'] => ({
  timer: undefined,
  prepared: undefined,
  endedWhilePreparing: undefined,
  reread: undefined,
  coldTimer: undefined,
  coldShown: false,
  checkAgainst: undefined,
  doubted: false,
  touch: undefined,
  lifetime: undefined,
  baseline: undefined,
  read: true,
  fresh: false,
  baselineDue: false,
  transcript: undefined,
  unreadSaid: false,
})

export const freshState = (): State => ({
  lastAttempt: undefined,
  pairing: freshPairing(),
  said: undefined,
  introduced: false,
  handingOver: false,
  turnWait: undefined,
  held: [],
  pending: undefined,
  pendingIn: undefined,
  later: undefined,
  asap: undefined,
  lastStop: undefined,
  asapScheduled: false,
  redelivering: false,
  answerRunning: false,
  afterHandoff: undefined,
  still: undefined,
  compactCheck: undefined,
  countdown: undefined,
  deferred: undefined,
  deliveredInto: undefined,
  preparing: false,
  returning: false,
  idle: freshIdle(),
  logLevel: 'off',
  badLogLevel: undefined,
})

files.hooks/idle-handoff.ts:
// The handoff after a long pause, the parts that need no host. The prompt cache lives for an hour (a subscription within its quota) or five
// minutes; after a longer pause the next message writes the whole conversation again at the write price. A handoff written while the cache
// is still warm lets the return start a fresh session instead. This module knows how to read the cache lifetime and the baseline (what a
// fresh session sends with its first message) from the transcript; the host tells a mod neither.

// A transcript up to this size is read whole; above it only its end, which holds the latest writes. Most long sessions pass 4 MiB.
export const READ_LIMIT_BYTES = 4_194_304
export const TAIL_BYTES = 262_144

export type Lifetime = '1h' | '5m'

export const readPlan = (size: number): 'read' | 'tail' => (size <= READ_LIMIT_BYTES ? 'read' : 'tail')

export type InputUsage = { input_tokens: number; cache_read_input_tokens: number; cache_creation_input_tokens: number }

export const baselineOfUsage = (u: InputUsage): number => u.input_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens

const count = (v: unknown): number => (typeof v === 'number' && Number.isFinite(v) ? v : 0)

// The main line's entries, in order: a subagent's (side chain) are left out. A line that is not an entry (the cut first line of an end read,
// a broken write) is skipped.
const mainEntries = function* (text: string): Generator<Record<string, unknown>> {
  for (const line of text.split('\n')) {
    let entry: unknown
    try {
      entry = JSON.parse(line)
    } catch {
      continue
    }
    if (typeof entry !== 'object' || entry === null) continue
    const e = entry as Record<string, unknown>
    if (e.isSidechain !== true) yield e
  }
}

// The main line's answers, in order.
const mainAnswers = function* (text: string): Generator<Record<string, unknown>> {
  for (const e of mainEntries(text)) {
    if (e.type !== 'assistant') continue
    const usage = (e.message as { usage?: unknown } | undefined)?.usage
    if (typeof usage === 'object' && usage !== null) yield usage as Record<string, unknown>
  }
}

// Whether the main line has answered at all: a transcript with answers and no write is a session that writes none (caching off), and
// reading it again tells nothing new; one with no answer yet is one the host has not caught up with.
export const hasAnswer = (text: string): boolean => !mainAnswers(text).next().done

// Whether the main line was compacted at or after `since` (ms). The host marks every compact with a `compact_boundary` entry, also one whose
// messages another hook gave and that no hook beneath it saw (measured on 2.1.302, a manual compact). A line with no readable time counts as none.
export const compactedSince = (text: string, since: number): boolean => {
  for (const e of mainEntries(text)) {
    if (e.type === 'system' && e.subtype === 'compact_boundary' && typeof e.timestamp === 'string' && Date.parse(e.timestamp) >= since) return true
  }
  return false
}

// The lifetime the last write of the main line used. Five minutes wins where a write has both: that part goes cold first. Claude Code writes
// it per entry (measured on 2.1.296, both lifetimes). Unknown where what was read holds no write. Every line is parsed: a read at the limit
// (4 MiB, 1836 lines of a real transcript) takes about 8 ms on a cold call (measured with Bun), and it runs at the first turn and when the handoff is due.
export const lifetimeOf = (text: string): Lifetime | undefined => {
  let found: Lifetime | undefined
  for (const usage of mainAnswers(text)) {
    const created = usage.cache_creation as Record<string, unknown> | undefined
    if (typeof created !== 'object' || created === null) continue
    if (count(created.ephemeral_5m_input_tokens) > 0) found = '5m'
    else if (count(created.ephemeral_1h_input_tokens) > 0) found = '1h'
  }
  return found
}

// The input of the first request of the main line: for a session resumed with no baseline kept for its project.
export const firstBaselineOf = (text: string): number | undefined => {
  for (const usage of mainAnswers(text)) {
    return baselineOfUsage({
      input_tokens: count(usage.input_tokens),
      cache_read_input_tokens: count(usage.cache_read_input_tokens),
      cache_creation_input_tokens: count(usage.cache_creation_input_tokens),
    })
  }
  return undefined
}

export const HOUR_MS = 3_600_000
// The handoff is written this long before the hour is up: the timer may come late, and writing takes seconds (a model call about 2 s, a
// command 20 to 34 s, measured). The touch is the start of the last request, so a long last request does not eat into it.
export const PREPARE_MARGIN_MS = 300_000
// The request that writes the handoff must start at least this long before the cache expires, or it writes the context anew. Only a late
// timer (after system sleep) comes this close.
export const PREPARE_MIN_LEFT_MS = 60_000
// Below the baseline plus this distance a fresh session costs more than carrying on with a cold cache: the handoff itself and what the
// fresh session reads again. Rounded from the cost model, with the re-reading estimated at 20000 tokens.
export const BASELINE_DISTANCE = 30_000
// A request that read this share of the context from the cache found it warm.
export const HIT_SHARE = 0.8

export const floorOf = (configured: number, baseline: number | undefined): number | undefined =>
  configured > 0 ? configured : baseline === undefined ? undefined : baseline + BASELINE_DISTANCE

export type PlanSnapshot = {
  on: boolean
  lifetime: Lifetime | undefined
  tokens: number | undefined
  floor: number | undefined
  handingOver: boolean
  // The session's timers the last stop named, one-shot and recurring: each begins a turn without the person, which would end the pause.
  timers: number
}

export const planVerdict = (s: PlanSnapshot): { plan: true } | { plan: false; why: string } => {
  if (!s.on) return { plan: false, why: 'switched off' }
  if (s.handingOver) return { plan: false, why: 'a handover runs' }
  if (s.lifetime !== '1h') return { plan: false, why: `cache lifetime ${s.lifetime ?? 'unknown'}` }
  if (s.timers > 0) return { plan: false, why: 'a timer of the session is set' }
  if (s.floor === undefined) return { plan: false, why: 'baseline unknown' }
  if (s.tokens === undefined) return { plan: false, why: 'context size unknown' }
  if (s.tokens < s.floor) return { plan: false, why: `context ${s.tokens} tokens below ${s.floor}` }
  return { plan: true }
}

export const prepareDueAt = (touch: number): number => touch + HOUR_MS - PREPARE_MARGIN_MS

export type FireSnapshot = { busy: string | undefined; lifetime: Lifetime | undefined; now: number; touch: number }

export const fireVerdict = (s: FireSnapshot): { go: true } | { go: false; why: string } => {
  if (s.busy !== undefined) return { go: false, why: s.busy }
  if (s.lifetime !== '1h') return { go: false, why: `cache lifetime ${s.lifetime ?? 'unknown'}` }
  if (s.now - s.touch >= HOUR_MS - PREPARE_MIN_LEFT_MS) return { go: false, why: 'the cache is about to expire or has' }
  return { go: true }
}

export const isHit = (usage: { cache_read_input_tokens: number } | undefined, tokens: number): boolean =>
  usage !== undefined && usage.cache_read_input_tokens >= HIT_SHARE * tokens

export type ReturnSnapshot = { now: number; touch: number; busy: boolean; attachments: boolean }

// The first message after the handoff was written. Cold is read off the clock at that moment and never from a mark a timer set: after system
// sleep a timer comes late, and a mark would take a cold cache for a warm one. A warm cache is cheap to read on, so only a cold one is left.
// Work that runs would report into a session that cannot place it, and an attachment cannot be carried over.
export const returnVerdict = (s: ReturnSnapshot): 'warm' | 'busy' | 'attachments' | 'cold' =>
  s.now - s.touch < HOUR_MS ? 'warm' : s.busy ? 'busy' : s.attachments ? 'attachments' : 'cold'

// How long the session sat idle, as the line after the switch says it.
export const idleFor = (ms: number): string => {
  const minutes = Math.floor(ms / 60_000)
  const h = Math.floor(minutes / 60)
  const m = minutes % 60
  return h === 0 ? `${m} min` : m === 0 ? `${h} h` : `${h} h ${m} min`
}

files.hooks/handoff.ts:
// The parts of a handoff through the user's own command that need no session: what to ask, where the file is, what the first message says.

import type { TaskSummary } from './pairing'

// The mod hands over at a size limit and not at the end of a piece of work, so the work is often in the middle of a task.
const MID_TASK =
  'This session is handed over because its context is large, often in the middle of a task. Cover everything the current task needs to carry on without reading it all again: the state of the work, the next step, the files it touches by path with what matters in each, and the decisions still open.'

// The command prints no path by itself; this is the request it gets as its argument: what the handoff has to cover, and the path line.
// The rule on the ending is said because a file named by `mktemp` gets none on macOS; it is said of the path, since the mod asks for nothing else.
export const ASK_FOR_PATH = `${MID_TASK} Only a path whose file name ends in .md is taken. End your final answer with one line: HANDOFF_PATH: <absolute path>`

const LINE = /^[\s>*_-]*HANDOFF_PATH:[ \t]*(.+?)\s*$/

// What the answer names is read by the mod, so it is held to an absolute markdown file that does not climb.
const usable = (path: string): boolean => /^(\/|[A-Za-z]:[\\/])/.test(path) && path.endsWith('.md') && !path.split(/[\\/]/).includes('..')

// Quotes, backticks and emphasis around the path, and a full stop after it, are the answer's prose and not part of the path.
const bare = (raw: string): string => raw.replace(/^[`'"*_]+|[`'"*_.]+$/g, '')

// The last usable line: an answer may quote the request before it gives the path.
export const handoffPath = (answer: string): string | undefined => {
  let found: string | undefined
  for (const line of answer.split('\n')) {
    const path = bare(LINE.exec(line)?.[1] ?? '')
    if (usable(path)) found = path
  }
  return found
}

export type Entry = { name: string; kind: string; mtimeMs: number; size: number }

// A handoff is a page or two; the limit only keeps a file that is not one from becoming the first message.
export const MAX_HANDOFF_BYTES = 200_000

// A file the answer names is checked against its entry in its directory: written since the command started, and of a size a handoff can be.
// Only a file that can be seen to fail is refused; one whose directory cannot be listed is let through.
export const unfit = (entry: Entry | undefined, file: string, since: number): { stage: 'path' | 'read'; reason: string } | undefined => {
  if (entry === undefined) return undefined
  if (entry.mtimeMs < since) return { stage: 'path', reason: `the handoff file ${file} was not written by this run` }
  if (entry.size > MAX_HANDOFF_BYTES) return { stage: 'read', reason: `the handoff file ${file} is too large (${entry.size} bytes)` }
  return undefined
}

// The first message with what the person typed while the handoff ran, so that nothing of it has to be sent on its own.
const TYPED_MEANWHILE = 'Typed while the handoff ran:'
// The message that came back after a long pause, and what followed it while the switch ran.
export const NEXT_MESSAGE = "The person's next message:"

export const withHeld = (message: string, held: readonly string[], heading = TYPED_MEANWHILE): string =>
  held.length === 0 ? message : `${message}\n\n${heading}\n${held.join('\n\n')}`

// What still runs when the handover begins, from the stop it was decided on: the standing tasks it did not wait for, and at the emergency
// brake the work it went past (empty otherwise). The fresh session cannot see the old one's tasks, and their results come to it.
export type Still = { standing: readonly TaskSummary[]; forced: readonly TaskSummary[] }

const STANDING = 'Still running from the previous session, not waited for because they are not expected to end by themselves:'
const FORCED = 'Still running, the handover did not wait for them; their results arrive here:'

// A shell task by its command, any other by its type and what Claude wrote it was for.
const taskLine = (t: TaskSummary) => `- ${t.type === 'shell' && t.command !== undefined ? t.command : `${t.type}: ${t.description}`} (task ${t.id})`

const section = (title: string, tasks: readonly TaskSummary[]) => (tasks.length === 0 ? [] : [[title, ...tasks.map(taskLine)].join('\n')])

export const firstMessage = (handoff: string, still?: Still): string =>
  [
    `Handoff from the previous session. Read it and carry on with the next step.\n\n${handoff}`,
    ...section(STANDING, still?.standing ?? []),
    ...section(FORCED, still?.forced ?? []),
  ].join('\n\n')

// The prompt the internal handoff asks the model when the user has none of their own. The `$.model.fork` call sees the whole history and has no tools, so it only has to say
// what the next session needs; the length is a guide, and a prompt file of the user's can set another.
export const DEFAULT_PROMPT = [
  'Write a handoff for the session that takes over this work. It starts with no memory of this conversation and must be able to carry on from your text alone.',
  MID_TASK,
  'Write about 4,000 to 6,000 characters, in the language of the conversation; keep code, commands, paths and error messages as they are.',
  'Cover, in this order:',
  '1. Goal: what the work is for, and the ticket or spec it follows, if any.',
  '2. State: what is done, what is under way, what is left.',
  '3. Decisions made, each with its reason.',
  '4. Attempts that failed, and why, so that they are not tried again.',
  '5. Next step: the one thing to do first.',
  '6. Open questions for the user.',
  '7. The end of the conversation, as close to word for word as you can: the last request, your last answer, and anything the user said that is not yet acted on.',
  '8. Suggested skills: the skills the new session should call for this work, by name.',
  'State facts only. Name files by their path. Leave out what the new session can read from the files itself. Write no greeting and no closing remarks.',
  'Redact secrets such as API keys, passwords and personal data; say that something was left out, not what it was.',
].join('\n')

// A directory as the host gives it may or may not end in a separator.
export const withoutTrailingSeparator = (dir: string): string => dir.replace(/[\\/]$/, '')

// Where the user's own prompt lives. The mod reads it and never writes it.
export const promptPath = (home: string): string => `${withoutTrailingSeparator(home)}/.claude/sweet-spot/handoff-prompt.md`

// A file that is missing, unreadable or blank leaves the prompt the mod brings.
export const promptFrom = (file: unknown): string => (typeof file === 'string' && file.trim() !== '' ? file.trim() : DEFAULT_PROMPT)

// `$.model.fork` cannot be cancelled, so the wait for it is limited here; an answer after the limit is not used.
export const MODEL_FORK_TIMEOUT_MS = 3 * 60_000

// What the host says when the user presses Esc during `$.session.compact`; it puts `$.session.compact:` in front, so the text is searched for
// in the refusal, not compared. A different wording makes Esc an ordinary refusal and the fallback runs after the cancel.
export const COMPACT_CANCELLED = 'Compaction canceled.' // host wording, measured 2.1.296

// How a tool result begins when the user pressed Esc or "No" at the permission prompt (a rule's denial reads differently). Searched for at the start
// of the result's text, which goes on with the host's own words, or with the user's hint. A different wording makes the decline unseen, and the
// run falls back after Esc as it did before.
export const USER_REJECTED = "The user doesn't want to proceed with this tool use." // host wording, measured 2.1.296

// What the model read and wrote for an answer: the share it read from the prompt cache says whether the cache was warm.
export type ModelForkUsage = { input_tokens: number; output_tokens: number; cache_read_input_tokens: number; cache_creation_input_tokens: number }

export type ModelForkAnswer = { isAnswered: true; text: string; usage?: ModelForkUsage } | { isAnswered: false; reason: string; status?: number | null }

type ModelForkUnanswered = Extract<ModelForkAnswer, { isAnswered: false }>

// The reasons `$.model.fork` gives nothing for that the mod knows, each in words for a person. The one list both the words and the log's kind read.
const MODEL_FORK_REASONS = {
  'nothing-to-fork': () => 'there is no conversation yet to write a handoff from',
  'api-error': answer => `the API failed${typeof answer.status === 'number' ? ` (status ${answer.status})` : ''}`,
  'empty-reply': () => 'the model replied with nothing',
  aborted: () => 'writing the handoff was aborted',
  timeout: () => `the model did not answer within ${MODEL_FORK_TIMEOUT_MS / 60_000} minutes`,
} satisfies Record<string, (answer: ModelForkUnanswered) => string>

const known = (reason: string): reason is keyof typeof MODEL_FORK_REASONS => Object.hasOwn(MODEL_FORK_REASONS, reason)

// The kind of reason an internal handoff gave nothing for, from a fixed set: a reason the mod does not know is the host's own words and stays out.
export const modelForkKind = (answer: ModelForkUnanswered): string => (known(answer.reason) ? answer.reason : 'other')

// What a `$.model.fork` call that gave no handoff says, in words for a person; a reason the mod does not know as the host gave it.
export const modelForkFailure = (answer: ModelForkUnanswered): string => (known(answer.reason) ? MODEL_FORK_REASONS[answer.reason](answer) : answer.reason)
